import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;

public class Main {
    static final class LengthFieldCodec {
        private final ByteBuffer cumulation = ByteBuffer.allocate(1024);

        static ByteBuffer encode(String text) {
            byte[] body = text.getBytes(StandardCharsets.UTF_8);
            ByteBuffer out = ByteBuffer.allocate(Integer.BYTES + body.length);
            out.putInt(body.length).put(body).flip();
            return out;
        }

        List<String> feed(ByteBuffer incoming) {
            cumulation.put(incoming);
            cumulation.flip();
            List<String> messages = new ArrayList<>();
            while (cumulation.remaining() >= Integer.BYTES) {
                cumulation.mark();
                int length = cumulation.getInt();
                if (length < 0 || length > 512)
                    throw new IllegalArgumentException("bad frame length: " + length);
                if (cumulation.remaining() < length) {
                    cumulation.reset();
                    break;
                }
                byte[] body = new byte[length];
                cumulation.get(body);
                messages.add(new String(body, StandardCharsets.UTF_8));
            }
            cumulation.compact();
            return messages;
        }
    }

    public static void main(String[] args) throws Exception {
        try (Selector selector = Selector.open();
             ServerSocketChannel server = ServerSocketChannel.open();
             SocketChannel client = SocketChannel.open()) {

            server.bind(new InetSocketAddress("127.0.0.1", 0));
            server.configureBlocking(false);
            server.register(selector, SelectionKey.OP_ACCEPT);
            int port = ((InetSocketAddress) server.getLocalAddress()).getPort();

            client.configureBlocking(false);
            client.connect(new InetSocketAddress("127.0.0.1", port));
            client.register(selector, SelectionKey.OP_CONNECT);

            LengthFieldCodec serverCodec = new LengthFieldCodec();
            LengthFieldCodec clientCodec = new LengthFieldCodec();
            ByteBuffer clientOutbound = LengthFieldCodec.encode("ping");
            SocketChannel accepted = null;
            String response = null;

            for (int loops = 0; response == null && loops < 1000; loops++) {
                selector.select(100);
                Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
                while (keys.hasNext()) {
                    SelectionKey key = keys.next();
                    keys.remove();
                    if (!key.isValid()) continue;

                    if (key.isAcceptable()) {
                        accepted = server.accept();
                        accepted.configureBlocking(false);
                        accepted.register(selector, SelectionKey.OP_READ);
                    }
                    if (key.isConnectable()) {
                        SocketChannel ch = (SocketChannel) key.channel();
                        if (ch.finishConnect())
                            key.interestOps(SelectionKey.OP_WRITE | SelectionKey.OP_READ);
                    }
                    if (key.isWritable()) {
                        SocketChannel ch = (SocketChannel) key.channel();
                        ch.write(clientOutbound);
                        if (!clientOutbound.hasRemaining()) {
                            key.interestOps(
                                (key.interestOps() & ~SelectionKey.OP_WRITE) | SelectionKey.OP_READ);
                        }
                    }
                    if (key.isReadable()) {
                        SocketChannel ch = (SocketChannel) key.channel();
                        ByteBuffer chunk = ByteBuffer.allocate(64);
                        int read = ch.read(chunk);
                        if (read < 0) throw new IOException("channel closed");
                        chunk.flip();
                        if (ch == client) {
                            List<String> messages = clientCodec.feed(chunk);
                            if (!messages.isEmpty()) response = messages.get(0);
                        } else {
                            for (String msg : serverCodec.feed(chunk)) {
                                ByteBuffer reply = LengthFieldCodec.encode(
                                    msg.toUpperCase(Locale.ROOT));
                                while (reply.hasRemaining()) ch.write(reply);
                            }
                        }
                    }
                }
            }
            if (accepted != null) accepted.close();

            System.out.println("server port: " + port);
            System.out.println("client response: " + response);
            assert "PING".equals(response);
        }
    }
}
